# Constants
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")

# Hyperparameter selection based on iteration number
iteration = 20  # Example iteration number
batch_size_options = [8, 16, 32]
learning_rate_options = [0.001, 0.0001, 0.00001]
conv_depth_options = [2, 3, 4]
dropout_options = [0.0, 0.2, 0.5]

batch_size = batch_size_options[iteration % 3]
lr = learning_rate_options[iteration % 3]
num_convs = conv_depth_options[iteration % 3]
dropout_rate = dropout_options[iteration % 3]

# DataLoader
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

class BirdCLEFModel(nn.Module):
    def __init__(self, num_classes=234, num_convs=3, dropout_rate=0.5):
        super(BirdCLEFModel, self).__init__()
        layers = []
        in_channels = 1
        for i in range(num_convs):
            out_channels = (i + 1) * 32
            layers.extend([
                nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
                nn.BatchNorm2d(out_channels),
                nn.ReLU(),
                nn.MaxPool2d(kernel_size=2, stride=2)
            ])
            in_channels = out_channels
        
        self.conv_layers = nn.Sequential(*layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Flatten(),
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_classes)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x)
        x = self.classifier(x)
        return torch.sigmoid(x)

# Model initialization
model = BirdCLEFModel(num_convs=num_convs, dropout_rate=dropout_rate).to('cuda')

# Training setup
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=0.001)
epochs = 2

# Training loop
def train_model(model, dataloader, criterion, optimizer, epochs):
    model.train()
    total_loss = 0
    batch_count = 0
    
    for epoch in range(epochs):
        for inputs, labels in tqdm(dataloader):
            if batch_count >= 10:  # Limit to 10 batches (first ~5000 samples)
                break
            
            inputs, labels = inputs.to('cuda'), labels.to('cuda')
            
            optimizer.zero_grad()
            outputs = model(inputs)
            loss = criterion(outputs, labels)
            loss.backward()
            optimizer.step()
            
            total_loss += loss.item()
            print(f"Epoch {epoch+1}/{epochs}, Batch {batch_count+1}, Loss: {loss.item()}")
            
            torch.cuda.empty_cache()
            batch_count += 1
    
    return total_loss / (batch_count * epochs)

# Validation function
def validate_model(model, dataloader):
    model.eval()
    all_labels = []
    all_preds = []
    
    with torch.no_grad():
        for inputs, labels in tqdm(dataloader):
            inputs, labels = inputs.to('cuda'), labels.to('cuda')
            outputs = model(inputs)
            
            all_labels.append(labels.cpu().numpy())
            all_preds.append(outputs.cpu().numpy())
    
    all_labels = np.concatenate(all_labels)
    all_preds = np.concatenate(all_preds)
    final_auc = roc_auc_score(all_labels, all_preds, average='weighted')
    
    return final_auc

# Training and validation
train_loss = train_model(model, train_loader, criterion, optimizer, epochs)

# Switch to evaluation mode for the same dataloader
train_loader.dataset.set_mode('eval')  # Assuming dataset has a method to switch modes
